using System.ComponentModel;
using Microsoft.Extensions.AI;

// --- Tool Definitions ---

/// <summary>
/// Provides web search capabilities for the research agent.
/// </summary>
public static class WebSearchTool
{
    [Description("Searches the web for the given query and returns relevant results with titles, URLs, and snippets.")]
    public static string Search([Description("The search query string")] string query)
    {
        // Simulated web search results for demonstration purposes.
        // In production, replace with a real search API (e.g., Bing Search API).
        Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");

        var results = query.ToLowerInvariant() switch
        {
            var q when q.Contains("quantum computing") => """
                1. "Quantum Computing in 2026: State of the Art" - nature.com
                   Snippet: Quantum computers have reached 1000+ logical qubits with error correction, enabling practical applications in drug discovery and cryptography.

                2. "IBM and Google Race to Quantum Advantage" - techreview.com
                   Snippet: Both companies have demonstrated quantum advantage on real-world optimization problems. IBM's Condor processor leads with 1,121 qubits.

                3. "Quantum Computing Market Report 2026" - marketsandmarkets.com
                   Snippet: The global quantum computing market is projected to reach $8.6 billion by 2027, growing at 32% CAGR. Key sectors: finance, pharma, logistics.
                """,
            var q when q.Contains("application") || q.Contains("use case") => """
                1. "Practical Quantum Computing Applications" - scientificamerican.com
                   Snippet: Drug molecule simulation reduced from years to days. Financial portfolio optimization shows 40% improvement over classical methods.

                2. "Quantum Machine Learning Breakthroughs" - arxiv.org
                   Snippet: Quantum neural networks demonstrate exponential speedup in specific pattern recognition tasks relevant to climate modeling.

                3. "Post-Quantum Cryptography Standards Finalized" - nist.gov
                   Snippet: NIST has finalized post-quantum cryptography standards as quantum computers pose increasing threat to RSA and ECC encryption.
                """,
            _ => $"""
                1. "Overview of {query}" - wikipedia.org
                   Snippet: A comprehensive overview covering the history, current state, and future directions of {query}.

                2. "Recent advances in {query}" - sciencedaily.com
                   Snippet: Researchers have made significant strides in {query}, with new developments expected to transform the field.

                3. "{query}: What You Need to Know in 2026" - technologyreview.com
                   Snippet: An accessible guide to the latest developments, key players, and future outlook for {query}.
                """
        };

        return results;
    }
}

/// <summary>
/// Provides note-taking capabilities for the agent to organize research findings.
/// </summary>
public static class NoteTakingTool
{
    private static readonly List<(string Category, string Content)> _notes = [];

    [Description("Saves a research note under a given category. Use this to organize findings as you research.")]
    public static string SaveNote(
        [Description("The category for this note (e.g., 'Key Facts', 'Statistics', 'Open Questions')")] string category,
        [Description("The content of the note")] string content)
    {
        _notes.Add((category, content));
        Console.WriteLine($"  [Tool] Note saved under \"{category}\"");
        return $"Note saved under '{category}': {content}";
    }

    [Description("Retrieves all saved research notes, optionally filtered by category.")]
    public static string GetNotes(
        [Description("Optional category filter. Pass empty string to get all notes.")] string category = "")
    {
        var filtered = string.IsNullOrEmpty(category)
            ? _notes
            : _notes.Where(n => n.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
            return "No notes found.";

        var result = string.Join("\n", filtered.Select(n => $"[{n.Category}] {n.Content}"));
        Console.WriteLine($"  [Tool] Retrieved {filtered.Count} note(s)");
        return result;
    }
}

// --- Main Program ---

var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing";

Console.WriteLine($"Research Agent Starting...");
Console.WriteLine($"Topic: {topic}");
Console.WriteLine(new string('-', 50));

// Configure the AI client with tool use
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

if (string.IsNullOrEmpty(openAiKey))
{
    Console.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    Console.WriteLine("Optionally set OPENAI_MODEL (default: gpt-4o).");
    return;
}

// Build the chat client with automatic function-calling
IChatClient client = new OpenAI.OpenAIClient(openAiKey)
    .GetChatClient(modelId)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Register tools
var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearchTool.Search),
        AIFunctionFactory.Create(NoteTakingTool.SaveNote),
        AIFunctionFactory.Create(NoteTakingTool.GetNotes),
    ]
};

// System prompt instructs the agent on its research workflow
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly and produce a summary.

        Follow this workflow:
        1. Search the web for the topic to get an overview.
        2. Search for specific aspects like applications, recent developments, or key players.
        3. Save important findings as notes using categories like "Key Facts", "Statistics", "Applications", "Future Outlook".
        4. After gathering enough information, retrieve your notes and produce a well-structured summary.

        Be thorough but concise. Cite sources where possible.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

Console.WriteLine("\nAgent is researching... (tool calls will appear below)\n");

// Run the agent loop
var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine(new string('-', 50));
Console.WriteLine("\n📋 RESEARCH SUMMARY\n");
Console.WriteLine(response.Text);

